from django.db import migrations


def reconstruir_historial(apps, schema_editor):
    """Da historial a los pedidos creados antes de que existiera.

    Solo se sabe con certeza cuándo se creó cada pedido: se registra como
    "pendiente" en su fecha de creación y, si ya avanzó, su estado actual con
    esa misma fecha (no hay registro de cuándo cambió realmente).
    """
    Pedido = apps.get_model('pedidos', 'Pedido')
    HistorialEstadoPedido = apps.get_model('pedidos', 'HistorialEstadoPedido')

    filas = []
    for pedido in Pedido.objects.filter(historial__isnull=True):
        filas.append(HistorialEstadoPedido(
            pedido=pedido, estado='pendiente', fecha=pedido.fecha_creacion
        ))
        if pedido.estado != 'pendiente':
            filas.append(HistorialEstadoPedido(
                pedido=pedido, estado=pedido.estado, fecha=pedido.fecha_creacion
            ))
    HistorialEstadoPedido.objects.bulk_create(filas)


